#!/usr/bin/env node
import {createHash} from 'node:crypto'; import {cp, mkdir, readFile, readdir, rm, writeFile} from 'node:fs/promises'; import {spawnSync} from 'node:child_process'; import {dirname,join,relative,resolve} from 'node:path'; import {fileURLToPath} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'../..'), sha=process.env.SOURCE_SHA, release=process.env.RELEASE_ID??`main-${sha?.slice(0,12)}`;
if(!/^[0-9a-f]{40}$/.test(sha??''))throw new Error('SOURCE_SHA must be lowercase 40 hex');
const roles=['postgres','redis','discover','coordinator','worker','query']; const images=Object.fromEntries(roles.map(k=>[k,process.env[`IMAGE_${k.toUpperCase()}`]]));
for(const [k,v] of Object.entries(images))if(!/^[^\s@]+@sha256:[0-9a-f]{64}$/.test(v??''))throw new Error(`IMAGE_${k.toUpperCase()} is not immutable`);
const digest=async p=>createHash('sha256').update(await readFile(p)).digest('hex');
const init=(await readdir(join(root,'deploy/initdb'),{withFileTypes:true})).filter(x=>x.isFile()).map(x=>`deploy/initdb/${x.name}`).sort(); const runtime=['deploy/run-migrations.sh','deploy/install-runtime.sh','deploy/systemd/rogi-collector-update.service','deploy/systemd/rogi-collector-update.timer','deploy/systemd/rogi-collector-backup.service','deploy/systemd/rogi-collector-backup.timer','tools/ops/fetch-release.py','tools/ops/production-status.py','tools/ops/backup-postgres.sh',...init];
const migrations=(await readdir(join(root,'deploy/migrations'),{withFileTypes:true})).filter(x=>x.isFile()&&x.name.endsWith('.sql')).map(x=>`deploy/migrations/${x.name}`).sort();
const manifest={schemaVersion:1,product:'rogi-collector',profile:'feedback',sourceSha:sha,releaseId:release,contractVersion:'v1',composeSha256:await digest(join(root,'deploy/compose.production.yaml')),runtimeFiles:await Promise.all(runtime.map(async path=>({path,sha256:await digest(join(root,path))}))),images,migrations:await Promise.all(migrations.map(async path=>({path,sha256:await digest(join(root,path))})))};
const out=join(root,'dist/release'), stage=join(root,'dist/.release-stage'); await rm(join(root,'dist'),{recursive:true,force:true}); await mkdir(stage,{recursive:true}); await mkdir(out,{recursive:true}); await writeFile(join(stage,'manifest.build.json'),JSON.stringify(manifest,null,2)+'\n');
for(const path of ['deploy','tools/ops'])await cp(join(root,path),join(stage,path),{recursive:true,filter:src=>!/(^|\/)(\.env|__pycache__)$/.test(src)});
let run=spawnSync('tar',['-C',stage,'-czf',join(out,'release-bundle.tar.gz'),'.'],{stdio:'inherit'}); if(run.status)process.exit(run.status??1); const sum=await digest(join(out,'release-bundle.tar.gz')); await writeFile(join(out,'release-bundle.tar.gz.sha256'),`${sum}  release-bundle.tar.gz\n`);
